async function MAIN_LOOP() {
  let trash = 0;
  for (;;) {
    trash = await MAIN_LOOP_1();
  }
}

async function MAIN_LOOP_1() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = false, tbl = 0, v_ = false, ptbl = true, obj1 = 0, tmp = 0, onum = 0;
  if (g.P_WON = await PARSER()) {
    icnt = get(g.P_PRSI, g.P_MATCHLEN);
    ocnt = get(g.P_PRSO, g.P_MATCHLEN);
    g.WAS_IT$ = await OBJECT_SUBSTITUTE(IT, g.P_IT_OBJECT);
    g.WAS_HIM$ = await OBJECT_SUBSTITUTE(HIM, g.P_HIM_OBJECT);
    onum = getb(g.P_SYNTAX, P_SBITS) & P_SONUMS;
    num = (ocnt == 0) || ((icnt == 0) && (onum == 2)) ? 0 : (ocnt > 1 ? (tbl = g.P_PRSO, icnt == 0 ? (obj = false) : (obj = get(g.P_PRSI, 1)), ocnt) : (icnt > 1 ? (ptbl = false, tbl = g.P_PRSI, obj = get(g.P_PRSO, 1), icnt) : 1));
    if (!obj && (icnt == 1)) {
      obj = get(g.P_PRSI, 1);
    }
    g.PERFORM_DEPTH = 0;
    if (g.PRSA == V.WALK) {
      v_ = await PERFORM_PRSA(g.PRSO);
    } else if (num == 0) {
      if (onum == 0) {
        v_ = await PERFORM_PRSA();
        g.PRSO = false;
      } else if (!g.LIT) {
        tell(S(g.TOO_DARK));
        await END_QUOTE();
      } else {
        tell("There isn't anything to ");
        tmp = get(g.P_ITBL, P_VERBN);
        if (isVerb(V.TELL)) {
          tell("talk to");
        } else if (g.P_OFLAG || g.P_MERGED) {
          printB(get(tmp, 0));
        } else {
          await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
        }
        tell("!\n");
        v_ = false;
        await END_QUOTE();
      }
    } else {
      g.P_NOT_HERE = 0;
      g.P_MULT = false;
      if (num > 1) {
        g.P_MULT = 1;
      }
      tmp = false;
      cnt = 0;
      loop1: for (;;) {
        if ((cnt = cnt + 1) > num) {
          if (g.P_NOT_HERE > 0) {
            tell("The ");
            if (!(g.P_NOT_HERE == num)) {
              tell("other ");
            }
            tell("object");
            if (!(g.P_NOT_HERE == 1)) {
              tell("s");
            }
            tell(" that you mentioned ");
            if (!(g.P_NOT_HERE == 1)) {
              tell("are");
            } else {
              tell("is");
            }
            tell("n't here.\n");
          } else if (!tmp) {
            tell(S(g.REFERRING), "\n");
          }
          break loop1;
        } else {
          if (ptbl) {
            obj1 = get(g.P_PRSO, cnt);
          } else {
            obj1 = get(g.P_PRSI, cnt);
          }
          g.PRSO = ptbl ? obj1 : obj;
          g.PRSI = ptbl ? obj : obj1;
          if ((num > 1) || eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL)) {
            if (await MULTIPLE_EXCEPTION$(obj1)) {
              continue loop1;
            } else if (isVerb(V.COMPARE_MANY)) {
            } else {
              if (obj1 == IT) {
                await DPRINT(g.P_IT_OBJECT);
              } else {
                await DPRINT(obj1);
              }
              tell(": ");
            }
          }
          tmp = true;
          g.PSEUDO_PRSO = (g.PRSO == PSEUDO_OBJECT) || false;
          v_ = await PERFORM_PRSA(g.PRSO, g.PRSI);
          if (v_ == M_FATAL) {
            break loop1;
          }
          if (g.P_MULT) {
            g.P_MULT = g.P_MULT + 1;
          }
        }
      }
    }
    if (!(v_ == M_FATAL)) {
      if (await GAME_VERB$()) {
      } else if (loc(g.WINNER)) {
        v_ = await apply(getProp(loc(g.WINNER), P.ACTION), M_END);
      }
    }
    if (v_ == M_FATAL) {
      g.P_CONT = false;
    }
  } else {
    g.P_CONT = false;
  }
  if (g.P_WON) {
    if (await GAME_VERB$()) {
    } else {
      v_ = await CLOCKER();
    }
    g.PRSA = false;
    g.PRSO = false;
    return g.PRSI = false;
  } else {
    return false;
  }
}

async function OBJECT_SUBSTITUTE(obj, var_) {
  let tmp = false, cnt = 0, icnt = 0, ocnt = 0;
  if (var_ && (await ACCESSIBLE$(var_))) {
    icnt = get(g.P_PRSI, g.P_MATCHLEN);
    ocnt = get(g.P_PRSO, g.P_MATCHLEN);
    loop1: for (;;) {
      if ((cnt = cnt + 1) > icnt) {
        break loop1;
      } else {
        if (eq(get(g.P_PRSI, cnt), obj)) {
          put(g.P_PRSI, cnt, var_);
          tmp = true;
          break loop1;
        }
      }
    }
    cnt = 0;
    loop2: for (;;) {
      if ((cnt = cnt + 1) > ocnt) {
        break loop2;
      } else {
        if (eq(get(g.P_PRSO, cnt), obj)) {
          put(g.P_PRSO, cnt, var_);
          tmp = true;
          break loop2;
        }
      }
    }
    return tmp;
  } else {
    return false;
  }
}

async function GAME_VERB$() {
  if (isVerb(V.TELL) && g.P_CONT) {
    return true;
  } else if (isVerb(V.HELP) && !g.PRSO && !(loc(PC) == g.HERE)) {
    return true;
  } else if (isVerb(V.QUIT, V.VERSION, V.BRIEF, V.SUPER_BRIEF, V.VERBOSE, V.$VERIFY, V.RESTART, V.SAVE, V.RESTORE, V.SCRIPT, V.UNSCRIPT, V.$SOUND, V.$RANDOM, V.$COMMAND, V.$RECORD, V.$UNRECORD, V.SCORE, V.TIME)) {
    return true;
  } else {
    return false;
  }
}

async function MULTIPLE_EXCEPTION$(obj1) {
  let l = loc(obj1);
  if (obj1 == NOT_HERE_OBJECT) {
    g.P_NOT_HERE = g.P_NOT_HERE + 1;
    return true;
  } else if (isVerb(V.TAKE) && g.PRSI && !(loc(g.PRSO) == g.PRSI)) {
    return true;
  } else if (!(await ACCESSIBLE$(obj1))) {
    return true;
  } else if (g.P_GETFLAGS == P_ALL) {
    if (g.PRSI && (g.PRSO == g.PRSI)) {
      return true;
    } else if (isVerb(V.TAKE) && !g.PRSI) {
      if ((!(l == g.WINNER || l == g.HERE || l == g.PRSI) && !(l == loc(g.WINNER)) && !(hasFlag(l, SURFACEBIT)) && !(hasFlag(l, SEARCHBIT))) || (!(hasFlag(obj1, TAKEBIT)) && !(hasFlag(obj1, TRYTAKEBIT)))) {
        return true;
      } else if (hasFlag(l, PERSON) || hasFlag(loc(l), PERSON)) {
        return true;
      } else if (await HELD$(g.PRSO)) {
        return true;
      } else if ((g.PRSO == DOME_LADDER) && (g.LADDER_TOP$ || g.LADDER_BOTTOM$)) {
        return true;
      } else if ((g.PRSO == CHAIN || g.PRSO == CHAIN_1 || g.PRSO == CHAIN_2) && (g.CHAIN_HOOKED$ || g.CHAIN_LOOPED$) && !(l == ELEVATOR_PIT || l == CS_BASEMENT)) {
        return true;
      } else if ((g.PRSO == PADLOCK) && g.PADLOCK_ON$) {
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.DROP, V.GIVE)) {
      if (!(loc(obj1) == g.WINNER)) {
        return true;
      } else if (hasFlag(obj1, WEARBIT)) {
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.PUT) && !(loc(g.PRSO) == g.WINNER) && (await HELD$(g.PRSO, g.PRSI))) {
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

