async function GLOBAL_CHECK(tbl) {
  let len = 0, rmg = 0, rmgl = 0, cnt = 0, obj = 0, obits = 0, foo = 0, nobj = 0;
  len = get(tbl, g.P_MATCHLEN);
  obits = g.P_SLOCBITS;
  if (rmg = getPropAddr(g.HERE, P.GLOBAL)) {
    rmgl = propSize(rmg) - 1;
    loop1: for (;;) {
      if (obj = getb(rmg, cnt)) {
        if (await THIS_IT$(obj, tbl)) {
          await OBJ_FOUND(obj, tbl);
        }
        if ((await SEARCH_CONTENTS$(obj)) && (nobj = first(obj))) {
          await SEARCH_LIST(obj, tbl, P_SRCALL);
        }
      }
      if (++cnt > rmgl) {
        break loop1;
      }
    }
  }
  if (rmg = getProp(g.HERE, P.THINGS)) {
    rmgl = get(rmg, 0);
    cnt = 0;
    loop2: for (;;) {
      if ((g.P_NAM == get(rmg, cnt + 2)) && ((get(g.P_ADJT, 0) == 0) || (await ZMEMQ(get(rmg, cnt + 1), g.P_ADJNT)))) {
        g.P_PNAM = g.P_NAM;
        g.LAST_PSEUDO_LOC = g.HERE;
        putProp(PSEUDO_OBJECT, P.ACTION, RANDOM_PSEUDO.id);
        foo = getPropAddr(PSEUDO_OBJECT, P.ACTION) - 5;
        put(foo, 0, get(g.P_NAM, 0));
        put(foo, 1, get(g.P_NAM, 1));
        await OBJ_FOUND(PSEUDO_OBJECT, tbl);
        break loop2;
      }
      cnt = cnt + 2;
      if (!(cnt < rmgl)) {
        break loop2;
      }
    }
  }
  if (eq(get(tbl, g.P_MATCHLEN), len)) {
    g.P_SLOCBITS = -1;
    g.P_TABLE = tbl;
    await DO_SL(GLOBAL_OBJECTS, 1, 1);
    return g.P_SLOCBITS = obits;
  } else {
    return false;
  }
}

async function DO_SL(obj, bit1, bit2) {
  let bts = 0;
  if (btst(g.P_SLOCBITS, bit1 + bit2)) {
    return await SEARCH_LIST(obj, g.P_TABLE, P_SRCALL);
  } else {
    if (btst(g.P_SLOCBITS, bit1)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCTOP);
    } else if (btst(g.P_SLOCBITS, bit2)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCBOT);
    } else {
      return true;
    }
  }
}

async function SEARCH_LIST(obj, tbl, lvl) {
  let robj = 0;
  if (obj = first(obj)) {
    for (;;) {
      if (!(lvl == P_SRCBOT) && getPropAddr(obj, P.SYNONYM) && (await THIS_IT$(obj, tbl))) {
        await OBJ_FOUND(obj, tbl);
      }
      if (obj == ELEVATOR_DOOR) {
        robj = await DOOR_AT_ELEVATOR();
      } else {
        robj = obj;
      }
      if (first(robj) && (await SEARCH_CONTENTS$(robj)) && (!(lvl == P_SRCTOP) || g.P_MOBY_FLAG)) {
        await SEARCH_LIST(robj, tbl, g.P_MOBY_FLAG || hasFlag(robj, SURFACEBIT) || hasFlag(robj, SEARCHBIT) ? P_SRCALL : P_SRCTOP);
      }
      if (!(obj = next(obj))) {
        return true;
      }
    }
  } else {
    return false;
  }
}

async function OBJ_FOUND(obj, tbl) {
  let ptr = 0;
  if (tbl == g.P_PRSO) {
    put(g.P_NAMW, 0, g.P_NAM);
    put(g.P_ADJW, 0, get(g.P_ADJNT, 1));
  } else if (tbl == g.P_PRSI) {
    put(g.P_NAMW, 1, g.P_NAM);
    put(g.P_ADJW, 1, get(g.P_ADJNT, 1));
  }
  ptr = get(tbl, g.P_MATCHLEN);
  put(tbl, ptr + 1, obj);
  return put(tbl, g.P_MATCHLEN, ptr + 1);
}

async function TAKE_CHECK() {
  return (await ITAKE_CHECK(g.P_PRSO, getb(g.P_SYNTAX, P_SLOC1))) && (await ITAKE_CHECK(g.P_PRSI, getb(g.P_SYNTAX, P_SLOC2)));
}

async function ITAKE_CHECK(tbl, ibits) {
  let ptr = 0, obj = 0, taken = 0;
  if ((ptr = get(tbl, g.P_MATCHLEN)) && (btst(ibits, SHAVE) || btst(ibits, STAKE))) {
    for (;;) {
      if ((ptr = ptr - 1) < 0) {
        return true;
      } else {
        obj = get(tbl, ptr + 1);
        if (obj == IT) {
          if (!g.P_IT_OBJECT) {
            tell(S(g.REFERRING), "\n");
          } else if (!(await ACCESSIBLE$(g.P_IT_OBJECT))) {
            tell("I don't see ");
            await THE_PRINT(g.P_IT_OBJECT);
            tell(" here.\n");
            return false;
          } else {
            obj = g.P_IT_OBJECT;
          }
        } else if (obj == HIM) {
          if (!g.P_HIM_OBJECT) {
            tell(S(g.REFERRING), "\n");
          } else if (!(await ACCESSIBLE$(g.P_HIM_OBJECT))) {
            tell("I don't see ");
            await THE_PRINT(g.P_HIM_OBJECT);
            tell(" here.\n");
            return false;
          } else {
            obj = g.P_HIM_OBJECT;
          }
        }
        if ((await HELD$(obj, g.WINNER)) || (await INTRINSIC$(obj)) || (loc(g.WINNER) == obj)) {
        } else {
          g.PRSO = obj;
          taken = true;
          if (hasFlag(obj, TRYTAKEBIT)) {
            taken = false;
          } else if (!(g.WINNER == PLAYER)) {
          } else if (btst(ibits, STAKE) && eq(await ITAKE(false), true)) {
          } else {
            taken = false;
          }
          if (!taken && btst(ibits, SHAVE)) {
            if (1 < get(tbl, g.P_MATCHLEN)) {
              tell(S(g.YOU_ARENT), "holding all those things!\n");
              return false;
            } else if (obj == NOT_HERE_OBJECT) {
              tell(S(g.YOU_CANT_SEE), "that here!\n");
              return false;
            } else if (g.WINNER == PLAYER) {
              tell(S(g.YOU_ARENT));
            } else {
              tell(S("It doesn't look like "));
              await THE_PRINT(g.WINNER);
              tell(" is ");
            }
            tell("holding ");
            if (obj == PSEUDO_OBJECT) {
              tell("that");
            } else {
              await THE_PRINT(obj);
            }
            await THIS_IS_IT(obj);
            tell(S(g.PERIOD));
            return false;
          } else if (taken && (g.WINNER == PLAYER) && !(g.PRSO == INTNUM)) {
            await TAKING_FIRST(obj);
          }
        }
      }
    }
  } else {
    return true;
  }
}

async function TAKING_FIRST(obj) {
  tell("(Taking ");
  await THE_PRINT(obj);
  tell(" first)\n");
  return true;
}

async function MANY_CHECK() {
  let loss = false, tmp = 0;
  if ((get(g.P_PRSO, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC1), SMANY))) {
    loss = 1;
  } else if ((get(g.P_PRSI, g.P_MATCHLEN) > 1) && !(btst(getb(g.P_SYNTAX, P_SLOC2), SMANY))) {
    loss = 2;
  }
  if (loss) {
    tell(S(g.YOU_CANT), "use multiple ");
    if (loss == 2) {
      tell("in");
    }
    tell("direct objects with \"");
    tmp = get(g.P_ITBL, P_VERBN);
    if (tmp == 0) {
      tell("tell");
    } else if (g.P_OFLAG || g.P_MERGED) {
      printB(get(tmp, 0));
    } else {
      await WORD_PRINT(getb(tmp, 2), getb(tmp, 3));
    }
    tell("\".\n");
    return false;
  } else {
    return true;
  }
}

async function ZMEMQ(itm, tbl, size = (-1)) {
  let cnt = 1;
  if (!tbl) {
    return false;
  }
  if (!(size < 0)) {
    cnt = 0;
  } else {
    size = get(tbl, 0);
  }
  for (;;) {
    if (itm == get(tbl, cnt)) {
      return tbl + (cnt * 2);
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function ZMEMQB(itm, tbl, size) {
  let cnt = 0;
  for (;;) {
    if (itm == getb(tbl, cnt)) {
      return true;
    } else if (++cnt > size) {
      return false;
    }
  }
}

async function LIT$(rm, rmbit = true) {
  let ohere = 0, lit = false;
  g.P_GWIMBIT = ONBIT;
  ohere = g.HERE;
  g.HERE = rm;
  if (rmbit && hasFlag(rm, ONBIT)) {
    lit = g.HERE;
  } else if ((g.HERE == ELEVATOR_PIT) && (hasFlag(ELEVATOR_DOOR_B, OPENBIT) || hasFlag(ELEVATOR_DOOR_1, OPENBIT))) {
    lit = CS_BASEMENT;
  } else if ((g.HERE == UNDER_ALCHEMY_LAB) && hasFlag(ALCHEMY_TRAP_DOOR, OPENBIT) && hasFlag(ALCHEMY_LAB, ONBIT)) {
    lit = ALCHEMY_LAB;
  } else if (hasFlag(g.WINNER, ONBIT) && (await HELD$(g.WINNER, rm))) {
    lit = g.WINNER;
  } else {
    put(g.P_MERGE, g.P_MATCHLEN, 0);
    g.P_TABLE = g.P_MERGE;
    g.P_SLOCBITS = -1;
    if (ohere == rm) {
      await DO_SL(g.WINNER, 1, 1);
      if (!(g.WINNER == PLAYER) && (loc(PLAYER) == rm)) {
        await DO_SL(PLAYER, 1, 1);
      }
    }
    if (hasFlag(loc(g.WINNER), VEHBIT) && !(hasFlag(loc(g.WINNER), OPENBIT))) {
      await DO_SL(loc(g.WINNER), 1, 1);
    }
    await DO_SL(rm, 1, 1);
    if (get(g.P_TABLE, g.P_MATCHLEN) > 0) {
      lit = get(g.P_TABLE, 1);
    }
  }
  g.HERE = ohere;
  g.P_GWIMBIT = 0;
  return lit;
}

async function THIS_IT$(obj, tbl) {
  let syns = 0, acnt = 0;
  if (hasFlag(obj, INVISIBLE)) {
    return false;
  } else if (g.P_NAM && !(await ZMEMQ(g.P_NAM, syns = getPropAddr(obj, P.SYNONYM), div(propSize(syns), 2) - 1))) {
    return false;
  } else if (!((acnt = get(g.P_ADJT, 0)) == 0) && !(syns = getPropAddr(obj, P.ADJECTIVE))) {
    return false;
  } else {
    if (!(acnt == 0)) {
      loop1: for (;;) {
        if (!(await ZMEMQB(get(g.P_ADJT, acnt), syns, propSize(syns) - 1))) {
          return false;
        }
        if ((acnt = acnt - 1) == 0) {
          break loop1;
        }
      }
    }
    if (!(g.P_GWIMBIT == 0) && !(hasFlag(obj, g.P_GWIMBIT))) {
      return false;
    }
  }
  return true;
}

