async function V_RESTORE() {
  let x = 0, y = 0;
  x = get(g.SOUND_FLAG, 0);
  loop1: for (;;) {
    await KILL_SOUNDS();
    break loop1;
  }
  if (await restore()) {
    return true;
  } else {
    loop2: for (;;) {
      if (x > 1) {
        await SOUNDS(div(x, 16), S_START, mod(x, 16));
      }
      break loop2;
    }
    tell(S(g.FAILED));
    return true;
  }
}

async function V_SAVE() {
  let x = 0;
  putb(g.OOPS_INBUF, 1, 0);
  x = await save();
  loop1: for (;;) {
    if (get(g.SOUND_FLAG, 0) > 1) {
      await SOUNDS(div(get(g.SOUND_FLAG, 0), 16), S_START, mod(get(g.SOUND_FLAG, 0), 16));
    }
    break loop1;
  }
  if (x == 0) {
    tell(S(g.FAILED));
    return true;
  } else {
    tell(S(g.OKAY));
    return true;
  }
}

