async function V_VERSION() {
  let cnt = 0;
  tell(S(g.LURKING_HORROR), "\nAn Interactive Horror\nCopyright (c) 1987 by Infocom, Inc. All rights reserved.\n", S(g.LURKING_HORROR), " is a trademark of Infocom, Inc.\nRelease ");
  printN(get(0, 1) & 2047);
  tell(" / Serial number ");
  cnt = 0;
  loop1: for (;;) {
    cnt = 18;
    loop2: for (;;) {
      if (cnt > 23) {
        break loop2;
      }
      printC(getb(0, cnt));
      cnt = cnt + 1;
    }
    break loop1;
  }
  return crlf();
}

