async function EMPTY_ALL(from, to) {
  let f = 0, n_ = 0, r = 0, _1st$ = false;
  f = 0;
  n_ = 0;
  loop1: for (;;) {
    f = first(from);
    loop2: for (;;) {
      if (!f) {
        break loop2;
      }
      n_ = next(f);
      if (hasFlag(f, TAKEBIT)) {
        _1st$ = true;
        await DPRINT(f);
        tell(": ");
        r = to ? (await PERFORM(V.PUT, f, to)) : (await PERFORM(V.DROP, f));
        if (r == M_FATAL) {
          return true;
        }
      }
      f = n_;
    }
    break loop1;
  }
  if (!_1st$) {
    await CTHE_PRINT(from);
    tell(" is empty.\n");
  }
  return true;
}

