async function ITAKE(vb = true) {
  let cnt = 0, obj = 0;
  if (!(hasFlag(g.PRSO, TAKEBIT))) {
    if (vb) {
      await TELL_YUKS();
    }
    return false;
  } else if (loc(g.PRSO) == g.WINNER) {
    tell(S(g.YOU_HAVE), "it", S(g.PERIOD));
    return false;
  } else if ((g.PRSO == CHAIN_1 || g.PRSO == CHAIN_2) && (await HELD$(CHAIN))) {
    remove(g.PRSO);
    return true;
  } else if (!(loc(loc(g.PRSO)) == g.WINNER) && (((await WEIGHT(g.PRSO)) + (await WEIGHT(g.WINNER))) > g.LOAD_ALLOWED)) {
    if (vb) {
      if (first(PLAYER)) {
        tell("Your load is too heavy");
      } else {
        tell("It's a little too heavy");
      }
      if (g.LOAD_ALLOWED < g.LOAD_MAX) {
        tell(", especially in light of your exhaustion.");
      } else {
        tell(".");
      }
      crlf();
    }
    return M_FATAL;
  } else if ((cnt = await CCOUNT(g.WINNER)) > g.FUMBLE_NUMBER) {
    if (vb) {
      tell("You're holding too many things and can't quite get them all arranged to take it as well.\n");
    }
    return M_FATAL;
  } else {
    if (hasFlag(g.PRSO, SLIMEBIT)) {
      await QUEUE(I_SLIME_OBJECT.id, 1);
    }
    await SCORE_OBJECT();
    move(g.PRSO, g.WINNER);
    clearFlag(g.PRSO, WEARBIT);
    clearFlag(g.PRSO, NDESCBIT);
    return true;
  }
}

async function SCORE_OBJECT(obj = false) {
  if (!obj) {
    obj = g.PRSO;
    if (hasFlag(obj, TOUCHBIT)) {
      return true;
    }
  }
  if (getPropAddr(obj, P.VALUE)) {
    g.SCORE = g.SCORE + getProp(obj, P.VALUE);
    putProp(obj, P.VALUE, 0);
  }
  return setFlag(obj, TOUCHBIT);
}

async function IDROP() {
  if (!(await HELD$(g.PRSO))) {
    tell(S(g.YOU_ARENT), "carrying ");
    await THE_PRSO();
    return false;
  } else if (!(loc(g.PRSO) == g.WINNER) && !(hasFlag(loc(g.PRSO), OPENBIT))) {
    await THIS_IS_IT(g.PRSO);
    await TELL_OPEN_CLOSED(loc(g.PRSO));
    return false;
  } else {
    clearFlag(g.PRSO, WEARBIT);
    move(g.PRSO, loc(g.WINNER));
    return true;
  }
}

async function CCOUNT(obj) {
  let cnt = 0, x = 0;
  x = 0;
  for (;;) {
    x = first(obj);
    for (;;) {
      if (!x) {
        return cnt;
        return true;
      }
      if ((x == HAND) && hasFlag(HAND, PERSON)) {
      } else if (hasFlag(x, WEARBIT)) {
      } else {
        cnt = cnt + 1;
      }
      x = next(x);
    }
  }
}

async function WEIGHT(obj) {
  let cont = 0, wt = 0;
  if ((obj == HAND) && hasFlag(HAND, PERSON)) {
    return true;
  } else if (!(hasFlag(obj, WEARBIT))) {
    cont = 0;
    loop1: for (;;) {
      cont = first(obj);
      loop2: for (;;) {
        if (!cont) {
          break loop2;
        }
        wt = wt + (await WEIGHT(cont));
        cont = next(cont);
      }
      break loop1;
    }
    return wt + getProp(obj, P.SIZE);
  } else {
    return false;
  }
}

async function GOTO(rm, v$ = true) {
  let olit = 0;
  g.OHERE = rm;
  await apply(getProp(g.HERE, P.ACTION), M_LEAVE);
  g.OHERE = g.HERE;
  olit = g.LIT;
  if (!(loc(loc(g.WINNER)) == ROOMS)) {
    move(loc(g.WINNER), rm);
  } else {
    move(g.WINNER, rm);
  }
  g.HERE = rm;
  g.LIT = await LIT$(g.HERE);
  if (!olit && !g.LIT && prob(80)) {
    (await JIGS_UP("One should never assume the dark is safe. Something just grabbed you from behind and dragged you off to its lair."));
    return true;
  }
  await apply(getProp(g.HERE, P.ACTION), M_ENTER);
  if (!(g.HERE == rm)) {
    return true;
  } else if (v$) {
    await V_FIRST_LOOK();
  }
  if (g.LIT) {
    await SCORE_OBJECT(rm);
  }
  return true;
}

