async function SOUNDS(n_, op = S_START, vol = 8) {
  if (op == 0) {
    op = S_START;
  }
  if ((get(g.SOUND_FLAG, 0) < 0) && (op == S_START)) {
    put(g.SOUND_FLAG, 0, 1);
    tell("\n[Use $SOUND to toggle sound usage on and off.]\n\n");
  }
  if (n_ == S_DRONE || n_ == S_ATTACK || n_ == S_PSYCHO || n_ == S_MONSTR || n_ == S_VOICE || n_ == S_ZOMBIE || n_ == S_CRETIN) {
    put(g.SOUND_FLAG, 1, (n_ * 16) + vol);
  }
  if (get(g.SOUND_FLAG, 0)) {
    if (op == S_STOP) {
      put(g.SOUND_FLAG, 0, 1);
      put(g.SOUND_FLAG, 1, 0);
    } else if (n_ == S_DRONE || n_ == S_ATTACK || n_ == S_PSYCHO || n_ == S_MONSTR || n_ == S_VOICE || n_ == S_ZOMBIE || n_ == S_CRETIN) {
      put(g.SOUND_FLAG, 0, (n_ * 16) + vol);
      put(g.SOUND_FLAG, 1, (n_ * 16) + vol);
    } else {
      put(g.SOUND_FLAG, 0, 1);
      put(g.SOUND_FLAG, 1, 0);
    }
    if (op == S_START) {
      return sound(n_, op, vol);
    } else {
      return sound(n_, op);
    }
  } else {
    return false;
  }
}

async function KILL_SOUNDS() {
  await SOUNDS(0, S_STOP);
  return await SOUNDS(0, S_CLEANUP);
}

async function V_$SOUND() {
  let x = 0, y = 0;
  x = get(g.SOUND_FLAG, 1);
  y = get(g.SOUND_FLAG, 0);
  tell("Sound ");
  if (y) {
    await KILL_SOUNDS();
    if (y != 1) {
      put(g.SOUND_FLAG, 1, y);
    } else {
      put(g.SOUND_FLAG, 1, 0);
    }
    put(g.SOUND_FLAG, 0, 0);
    tell("off.\n");
    return true;
  } else {
    put(g.SOUND_FLAG, 0, 1);
    if (x) {
      loop1: for (;;) {
        await SOUNDS(div(x, 16), S_START, mod(x, 16));
        break loop1;
      }
    }
    tell("on.\n");
    return true;
  }
}

