async function FLASK_F() {
  if (g.PRSO == FLASK) {
    if (isVerb(V.EXAMINE)) {
      tell(S("This is a large "), "metal flask, about the size of a water cooler bottle. ");
      if (hasFlag(FLASK, OPENBIT)) {
        tell("The flask is open");
        if (loc(NITROGEN) == FLASK) {
          tell(", and a thin, cold mist flows out of it");
        }
        tell(S(g.PERIOD));
        return true;
      } else {
        return await TELL_OPEN_CLOSED(FLASK);
      }
    } else if (isVerb(V.RUB)) {
      tell("The metal of the flask is ");
      if (loc(NITROGEN) == FLASK) {
        tell("very ");
      }
      tell("cold.\n");
      return true;
    } else if (isVerb(V.OPEN)) {
      if (!(hasFlag(FLASK, OPENBIT))) {
        setFlag(FLASK, OPENBIT);
        tell("You open the flask");
        if (loc(NITROGEN) == FLASK) {
          move(MIST, g.HERE);
          await QUEUE(I_NITROGEN_GOES.id, 3);
          tell(", and a cold, white mist boils out");
        }
        tell(S(g.PERIOD));
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.CLOSE)) {
      if (hasFlag(FLASK, OPENBIT)) {
        await DEQUEUE(I_NITROGEN_GOES.id);
        await QUEUE(I_MIST_GOES.id, 2);
        clearFlag(FLASK, OPENBIT);
        tell("You screw the flask closed.\n");
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.FILL)) {
      return await CANT_FILL_IT();
    } else if (isVerb(V.POUR) && (loc(NITROGEN) == FLASK)) {
      await NEW_PRSO(NITROGEN);
      return true;
    } else {
      return false;
    }
  } else if ((isVerb(V.PUT) && (g.PRSI == FLASK)) && (getProp(g.PRSO, P.SIZE) > getProp(FLASK, P.CAPACITY))) {
    tell("The neck of ");
    await THE_PRINT(FLASK);
    tell(" is too small.\n");
    return true;
  } else {
    return false;
  }
}

