async function NITROGEN_F() {
  if (isVerb(V.EXAMINE)) {
    tell("The flask contains a clear, ", D(NITROGEN), " with a thin white mist boiling off of it.\n");
    return true;
  } else if (isVerb(V.TAKE, V.RUB)) {
    tell("The liquid is extremely cold. In fact, you burn your finger on it.\n");
    return true;
  } else if (isVerb(V.SMELL)) {
    tell("The liquid has no smell.\n");
    return true;
  } else if (isVerb(V.POUR, V.PUT, V.DROP, V.THROW)) {
    remove(NITROGEN);
    await DEQUEUE(I_NITROGEN_GOES.id);
    await QUEUE(I_MIST_GOES.id, 2);
    if (g.PRSI == FLASK) {
      tell(S(g.GOOD_TRICK));
      return true;
    } else if (g.PRSI && hasFlag(g.PRSI, PERSON) && !(g.PRSI == ME || g.PRSI == HAND)) {
      await SWAP_VERB(V.ATTACK);
      return true;
    } else {
      tell("The freezing liquid pours out");
      if (g.PRSI) {
        tell(" onto ");
        await THE_PRINT_PRSI();
      }
      tell(", boiling into cold mist almost immediately");
      if (g.PRSI) {
        if ((await HELD$(g.PRSI)) || (await INTRINSIC$(g.PRSI))) {
          (await JIGS_UP(", but not before it freezes you as well."));
          return M_FATAL;
        } else if (hasFlag(g.PRSI, SLIMEBIT)) {
          clearFlag(g.PRSI, SLIMEBIT);
        } else if (hasFlag(g.PRSI, TAKEBIT)) {
          remove(g.PRSI);
          tell(", but ");
          await THE_PRINT_PRSI();
          tell(" freezes and then shatters from the cold");
        }
      }
      tell(".\n");
      return true;
    }
  } else {
    return false;
  }
}

async function I_NITROGEN_GOES() {
  if (loc(NITROGEN) == FLASK) {
    await QUEUE(I_NITROGEN_GOES.id, 3);
    g.NITROGEN_CNT = g.NITROGEN_CNT - 1;
    if (g.NITROGEN_CNT == 0) {
      await DEQUEUE(I_NITROGEN_GOES.id);
      await QUEUE(I_MIST_GOES.id, 2);
      remove(NITROGEN);
      return false;
    } else {
      if (await ACCESSIBLE$(FLASK)) {
        tell("\nCold white mist continues to boil out of the flask.\n");
        return true;
      } else {
        return false;
      }
    }
  } else {
    return false;
  }
}

