async function FLOOR_BUTTON_F() {
  let old = 0;
  if (isVerb(V.PUSH)) {
    if (g.PRSO == BASEMENT_BUTTON) {
      g.P_NUMBER = 0;
    }
    if (g.P_NUMBER > 3) {
      tell("There are only three floors and a basement in this building.\n");
      return true;
    } else if (g.P_NUMBER == g.ELEVATOR_LOC) {
      if (g.HERE == CS_ELEVATOR_ROOM) {
        tell("The button doesn't light.\n");
        return true;
      } else {
        return true;
      }
    } else {
      old = get(g.BUTTONS, g.P_NUMBER);
      if (!(btst(old, E_GO))) {
        put(g.BUTTONS, g.P_NUMBER, old | E_GO);
        await QUEUE(I_ELEVATOR_MOVES.id, 1);
        if (g.ELEVATOR_STOPPED$) {
          await PICK_ELEVATOR_DIRECTION();
        }
        if (g.HERE == CS_ELEVATOR_ROOM) {
          tell("The button for the ", S(get(g.FLOOR_NAMES, g.P_NUMBER)), S(" begins to glow.\n"));
          return true;
        } else {
          return true;
        }
      } else {
        if (g.HERE == CS_ELEVATOR_ROOM) {
          tell(S(g.ALREADY_GLOWING));
          return true;
        } else {
          return true;
        }
      }
    }
  } else {
    return false;
  }
}

