async function UP_BUTTON_F(bit = E_UP) {
  let old = 0, floor = 0;
  floor = getProp(g.HERE, P.FLOOR);
  old = get(g.BUTTONS, floor);
  if (isVerb(V.EXAMINE)) {
    if (btst(old, bit)) {
      await CTHE_PRINT_PRSO();
      tell(" is glowing.\n");
      return true;
    } else {
      return false;
    }
  } else if (isVerb(V.PUSH)) {
    if (!(btst(old, bit))) {
      if (g.ELEVATOR_STOPPED$ && eq(getProp(g.HERE, P.FLOOR), g.ELEVATOR_LOC)) {
        await DEQUEUE(I_ELEVATOR_MOVES.id);
        await QUEUE(I_ELEVATOR_DOOR_OPENS.id, 1);
        tell("You push ");
        await THE_PRINT_PRSO();
        tell(S(g.PERIOD));
        return true;
      } else {
        put(g.BUTTONS, floor, bit | old);
        if (g.ELEVATOR_STOPPED$) {
          await PICK_ELEVATOR_DIRECTION();
          if (!(await QUEUED$(I_ELEVATOR_DOOR_CLOSES.id))) {
            await QUEUE(I_ELEVATOR_MOVES.id, 1, true);
          }
        }
        await CTHE_PRINT_PRSO();
        tell(S(" begins to glow.\n"));
        return true;
      }
    } else {
      tell(S(g.ALREADY_GLOWING));
      return true;
    }
  } else {
    return false;
  }
}

