async function PADLOCK_F() {
  let lp = 0;
  if (isVerb(V.EXAMINE)) {
    tell(S("The padlock has "), "been spray painted many times by graffiti artists. It's currently fluorescent purple. In spite of the many coats of paint, the lock manages to be rusty and, in fact, almost slimy-looking. The padlock is ");
    if (hasFlag(PADLOCK, LOCKED)) {
      tell("locked");
      if (g.PADLOCK_ON$) {
        tell(" to ");
        await THE_PRINT(g.PADLOCK_ON$);
      }
    } else {
      tell("unlocked");
    }
    tell(S(g.PERIOD));
    return true;
  } else if (isVerb(V.READ)) {
    tell(S("The padlock has "), "no identifiable brand or symbol on it.\n");
    return true;
  } else if (isVerb(V.TAKE) && g.PADLOCK_ON$) {
    return await UNLOCK_PADLOCK_FIRST();
  } else if (isVerb(V.PUT_ON)) {
    await SWAP_VERB(V.LOCK);
    return true;
  } else if (isVerb(V.LOCK, V.CLOSE, V.TIE)) {
    if (g.PADLOCK_ON$) {
      return await ALREADY_LOCKED_TO();
    } else if (g.PRSI == false || g.PRSI == MASTER_KEY) {
      setFlag(g.PRSO, LOCKED);
      clearFlag(g.PRSO, OPENBIT);
      tell("Okay, you've now closed the padlock.\n");
      return true;
    } else if ((g.PRSI == PADLOCK) && !(g.PRSO == CHAIN || g.PRSO == CHAIN_1 || g.PRSO == CHAIN_2 || g.PRSO == ACCESS_HATCH)) {
      return await CANT_LOCK(g.PRSO);
    } else if (g.PRSO == PADLOCK) {
      if (g.PRSI == CHAIN || g.PRSI == CHAIN_1 || g.PRSI == CHAIN_2 || g.PRSI == ACCESS_HATCH) {
        await PERFORM(V.LOCK, g.PRSI, PADLOCK);
        return true;
      } else {
        return await CANT_LOCK(g.PRSI);
      }
    } else {
      return false;
    }
  } else if (isVerb(V.UNLOCK) || (isVerb(V.OPEN) && hasFlag(PADLOCK, LOCKED))) {
    if (!(hasFlag(g.PRSO, LOCKED))) {
      tell(S(g.IT_ALREADY_IS));
      return true;
    } else if (!g.PRSI) {
      tell(S(g.YOU_HAVE_TO), "use a key for that.\n");
      return true;
    } else if (g.PRSI == MASTER_KEY) {
      if (g.PADLOCK_ON$) {
        lp = loc(PADLOCK);
        clearFlag(lp, LOCKED);
        if (loc(lp) == LOCAL_GLOBALS) {
          move(PADLOCK, g.HERE);
        } else {
          move(PADLOCK, loc(lp));
        }
      }
      clearFlag(PADLOCK, NDESCBIT);
      clearFlag(PADLOCK, LOCKED);
      setFlag(PADLOCK, OPENBIT);
      tell("The lock, though rusty and unwilling, opens");
      if (g.PADLOCK_ON$) {
        tell(", releasing ");
        await THE_PRINT(g.PADLOCK_ON$);
      }
      g.PADLOCK_ON$ = false;
      tell(S(g.PERIOD));
      return true;
    } else if (g.PRSI == KEY_1 || g.PRSI == KEY_2 || g.PRSI == KEY_3 || g.PRSI == KEY_4) {
      await CTHE_PRINT_PRSI();
      tell(S(" doesn't appear to "), "open this lock.\n");
      return true;
    } else if (!g.PRSI) {
      tell(S("You don't have "), "a key.\n");
      return true;
    } else {
      tell(S(g.YOU_CANT), "open this lock with ");
      await PRINTA_PRSI();
      tell("!\n");
      return true;
    }
  } else if (isVerb(V.MUNG, V.CUT, V.ATTACK) && (g.PRSO == PADLOCK)) {
    if (g.PRSI == SMOOTH_STONE) {
      tell("You smash against the padlock with the stone. As expected, there is no result. In fact, both stone and padlock are unmarred.\n");
      return true;
    } else if (g.PRSI == AXE) {
      tell("All you succeed in doing is blunting the axe a little.\n");
      return true;
    } else {
      tell("In spite of its present defacement, this is a good padlock. Your feeble attempts have no effect.\n");
      return true;
    }
  } else {
    return false;
  }
}

