async function HEAT(obj) {
  let h = getProp(obj, P.HEAT);
  if (h >= 20) {
    return "radioactive";
  } else if (h >= 16) {
    return "volcanic";
  } else if (h >= 12) {
    return "hot";
  } else if (h >= 8) {
    return "warm";
  } else if (h >= 4) {
    return "lukewarm";
  } else {
    return "cold";
  }
}

